#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==2,"usage local_TR_lift OUT");fs::path out=argv[1];rref_option_t opt;opt->pool.reset(1);auto start=std::chrono::steady_clock::now();auto C=read_matrix(out/"boundary_local_TR_coefficients.wxf");PrivateCarrierChart pc(transpose(C));size_t private_coverage=0;for(auto x:pc.columns)if(x>=0)++private_coverage;Mat aug(C.nrow,C.ncol+C.nrow);for(size_t r=0;r<C.nrow;++r){aug[r]=C[r];aug[r].push_back(index(C.ncol+r),Q(1));}auto old=opt->col_weight;opt->col_weight=[old,n=C.ncol](int64_t c){return c<int64_t(n)?old(c):-1;};auto piv=sparse_mat_rref_reconstruct(aug,opt);opt->col_weight=old;Mat H(C.ncol,C.nrow);size_t rank=0;for(auto&batch:piv)for(auto[r,c]:batch){require(size_t(c)<C.ncol,"forbidden augmented pivot");++rank;for(auto[j,x]:aug[r])if(size_t(j)>=C.ncol)H[c].push_back(index(size_t(j)-C.ncol),x);}require(rank==C.ncol,"C rank incomplete");aug.clear();require(equal(mul(H,C),identity(C.ncol)),"H C exact identity");write(out/"boundary_local_TR_lift.wxf",H);std::cout<<"LIFT rank="<<rank<<" H_nnz="<<H.nnz()<<" H.C=I seconds="<<seconds(start)<<std::endl;auto tf=read_matrix(out/"boundary_local_rref.wxf"),J=read_matrix(out/"suffix_TR92_to_TF175.wxf"),rr=read_matrix(out/"boundary_local_TR_rref.wxf");auto D=mul(H,tf);require(equal(mul(D,transpose(kron(identity(88),J))),rr),"D restriction equals TR RREF");write(out/"boundary_local_TR_TF_representatives.wxf",D);std::ofstream j(out/"boundary_local_TR_lift.json");j<<"{\"all_checks_pass\":true,\"private_selector_coverage\":"<<private_coverage<<",\"H_dimensions\":["<<H.nrow<<','<<H.ncol<<"],\"H_nonzeros\":"<<H.nnz()<<",\"D_dimensions\":["<<D.nrow<<','<<D.ncol<<"],\"D_nonzeros\":"<<D.nnz()<<",\"exact_checks\":[\"H.C=I7632\",\"D=H.TFLocal\",\"D.(id88 tensor J)^T=TRlocalRREF\"],\"method\":\"Sparse modular RREF of[C|I], pivots restricted to C columns; full rational residual certificates\",\"scope\":\"Exact local equation representatives to preserve the affine RHS under removal of redundant seam equations. No global candidate solved.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPLETE D_nnz="<<D.nnz()<<" seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
